        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find the line color (non-zero value that appears in grid lines)
    # Count frequency of non-zero values
    from collections import Counter
    freq = Counter()
    for r in grid:
        for c in r:
            if c != 0:
                freq[c] += 1

    if not freq:
        return grid

